import {test} from 'node:test';
import assert from 'node:assert/strict';
import {resignationBrowserPushSource,RESIGNATION_BROWSER_BRANCH,RESIGNATION_BROWSER_WORKFLOW} from './resignation-browser-push.mjs';
const sha='a'.repeat(40),ref='refs/heads/'+RESIGNATION_BROWSER_BRANCH,repo='StradaverseHub/ai-hr';
const event=()=>({repository:{full_name:repo},ref,after:sha,deleted:false,commits:[{id:sha,modified:[RESIGNATION_BROWSER_WORKFLOW]}]});
const env=()=>({GITHUB_EVENT_NAME:'push',GITHUB_REPOSITORY:repo,GITHUB_REF:ref,GITHUB_SHA:sha,AIHR_WORKFLOW_SHA:sha,AIHR_WORKFLOW_REF:repo+'/'+RESIGNATION_BROWSER_WORKFLOW+'@'+ref});
test('binds this exact candidate push to the actual clean workflow-source checkout',()=>{assert.deepEqual(resignationBrowserPushSource(event(),env(),sha,''),{sha,branch:RESIGNATION_BROWSER_BRANCH});});
for(const [label,change]of Object.entries({repository:e=>e.repository.full_name='Other/repo',branch:e=>e.ref='refs/heads/main',tag:e=>e.ref='refs/tags/example',deleted:e=>e.deleted=true,malformed:e=>e.after='main',path:e=>e.commits[0].modified=['app/me/page.tsx'],pullRequest:e=>e.pull_request={number:1}}))test('refuses altered event '+label,()=>{const value=event();change(value);assert.throws(()=>resignationBrowserPushSource(value,env(),sha,''));});
for(const key of ['GITHUB_EVENT_NAME','GITHUB_REPOSITORY','GITHUB_REF','GITHUB_SHA','AIHR_WORKFLOW_SHA','AIHR_WORKFLOW_REF'])test('refuses mismatched runtime '+key,()=>{assert.throws(()=>resignationBrowserPushSource(event(),{...env(),[key]:'unexpected'},sha,''));});
test('refuses a moved or dirty checkout independently of event metadata',()=>{assert.throws(()=>resignationBrowserPushSource(event(),env(),'b'.repeat(40),''));assert.throws(()=>resignationBrowserPushSource(event(),env(),sha,' M app/me/page.tsx'));});
